use strict;
use warnings;
use File::Find;
use File::Basename;

my $root = "/bench/repo";
my $internal = "$root/internal";

sub is_go {
  my ($path, $tests) = @_;
  return 0 unless $path =~ /\.go$/;
  return 0 if $path =~ m{/proto/gen/} || $path =~ m{/web/} || $path =~ m{/node_modules/};
  return 0 if !$tests && $path =~ /_test\.go$/;
  return 1;
}

my @decls;
find({ wanted => sub {
  return unless is_go($File::Find::name, 1);
