find({ wanted => sub {
  return unless is_go($File::Find::name, 1);
  push @go_files, $File::Find::name;
}, no_chdir => 1 }, $root);

my %name_counts;
my %name_sites;
my %names = map { $_ => 1 } keys %name_to_decls;

for my $path (@go_files) {
  open my $fh, "<", $path or next;
  my $i = 0;
  while (my $line = <$fh>) {
    $i++;
    my $is_decl = 0;
    my $decl_name;
