  my $cnt = $name_counts{$name};
  my @nd = @{$name_to_decls{$name}};
  my @recvs = map { $_->{recv} || "(func)" } @nd;
  my @paths = map { my $p = $_->{path}; $p =~ s/^\Q$root\E\///; $p } @nd;
