  my ($path, $tests) = @_;
  return 0 unless $path =~ /\.go$/;
  return 0 if $path =~ m{/proto/gen/} || $path =~ m{/web/} || $path =~ m{/node_modules/} || $path =~ m{/\.git/};
  return 0 if !$tests && $path =~ /_test\.go$/;
  return 1;
}

my @internal_files = grep { is_go($_, 0) } split /\n/, `find "$internal" -name "*.go" -type f`;
my @go_all = grep { is_go($_, 1) } split /\n/, `find "$root" -name "*.go" -type f ! -path "*/.git/*" ! -path "*/web/*" ! -path "*/proto/gen/*"`;
my @go_prod = grep { is_go($_, 0) } @go_all;

my @decls;
for my $path (@internal_files) {
  open my $fh, "<", $path or next;
  my $i = 0;
  while (my $line = <$fh>) {
    $i++;
    if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/) {
      my ($recv, $name) = ($1, $2);
      my $recv_type;
      if (defined $recv) {
        my @p = split /\s+/, $recv;
        $recv_type = $p[-1];
        $recv_type =~ s/^\*//;
      }
      my $pkg = $path;
      $pkg =~ s{.*/internal/}{internal/};
      $pkg =~ s{/[^/]+$}{};
      # package name from file dir
      my $dir = $path;
      $dir =~ s{/[^/]+$}{};
      my $pkgname = $dir;
      $pkgname =~ s{.*/}{};
      push @decls, {
        name => $name,
        recv => $recv_type,
        path => $path,
        line => $i,
        pkg => $pkgname,
        key => ($recv_type ? "$pkgname.$recv_type.$name" : "$pkgname.$name"),
      };
    }
  }
  close $fh;
}

# unique names
my %name_count_decls;
for my $d (@decls) { $name_count_decls{$d->{name}}++; }
my @unique = grep { $name_count_decls{$_->{name}} == 1 } @decls;

print "Non-test decls: ", scalar(@decls), " unique-named: ", scalar(@unique), "\n";

sub count_in {
  my ($files, $name) = @_;
  my $n = 0;
  my @sites;
  my $pat = qr/(?:[\w.]+\.)?\Q$name\E\s*\(/;
  for my $path (@$files) {
    open my $fh, "<", $path or next;
    my $i = 0;
    while (my $line = <$fh>) {
      $i++;
      # skip declaration
      if ($line =~ /^func\s+(?:\([^)]+\)\s+)?\Q$name\E\s*\(/) { next; }
      while ($line =~ /$pat/g) {
        $n++;
        if (@sites < 5) {
          my $rel = $path; $rel =~ s/^\Q$root\E\///;
          my $snip = $line; chomp $snip; $snip = substr($snip,0,100);
          push @sites, "$rel:$i: $snip";
        }
      }
    }
    close $fh;
  }
  return ($n, \@sites);
}

# Count unique names in prod and all
my @scored;
for my $d (@unique) {
  my ($all, $as) = count_in(\@go_all, $d->{name});
  my ($prod, $ps) = count_in(\@go_prod, $d->{name});
  push @scored, { d => $d, all => $all, prod => $prod, as => $as, ps => $ps };
}

print "\n=== TOP UNIQUE NAMES BY ALL CALLS ===\n";
my @byall = sort { $b->{all} <=> $a->{all} } @scored;
for my $idx (0..20) {
  my $s = $byall[$idx]; last unless $s;
  my $rel = $s->{d}{path}; $rel =~ s/^\Q$root\E\///;
  print sprintf("%3d all / %3d prod  %-36s %s:%d\n", $s->{all}, $s->{prod}, $s->{d}{key}, $rel, $s->{d}{line});
}

print "\n=== TOP UNIQUE NAMES BY PROD CALLS ===\n";
my @byprod = sort { $b->{prod} <=> $a->{prod} } @scored;
for my $idx (0..20) {
  my $s = $byprod[$idx]; last unless $s;
  my $rel = $s->{d}{path}; $rel =~ s/^\Q$root\E\///;
  print sprintf("%3d prod / %3d all  %-36s %s:%d\n", $s->{prod}, $s->{all}, $s->{d}{key}, $rel, $s->{d}{line});
}

print "\n=== SAMPLE SITES TOP ALL ===\n";
for my $idx (0..6) {
  my $s = $byall[$idx]; last unless $s;
  print "\n--- $s->{d}{key} all=$s->{all} prod=$s->{prod} ---\n";
  for my $site (@{$s->{as}}) { print "  $site\n"; }
}
'

